(async () => {
  const { existsSync } = await import('node:fs');
  const inputPath = process.env.INPUT_PATH;
  const outputPath = process.env.OUTPUT_PATH;
  if (!inputPath) throw new Error('Missing INPUT_PATH');
  if (!outputPath) throw new Error('Missing OUTPUT_PATH');
  if (!existsSync(inputPath)) throw new Error('Input file does not exist');
  globalThis.inputPath = inputPath;
  globalThis.outputPath = outputPath;
})();

(async () => {
  const { default: jspModule } = await import('jsparsers');
  const jsp = jspModule || (await import('jsparsers')).default;
  const xml = jsp.xml();
  await xml.readFile(globalThis.inputPath);
  const tomlStr = xml.toml();
  globalThis.tomlStr = tomlStr;
})();

(async () => {
  const { writeFileSync } = await import('node:fs');
  writeFileSync(globalThis.outputPath, globalThis.tomlStr, 'utf8');
  console.log(JSON.stringify({ output_path: globalThis.outputPath }));
})();
